CREATE TABLE IF NOT EXISTS saliyah_projects (id TEXT PRIMARY KEY,ministry_id INTEGER NOT NULL,project_type TEXT NOT NULL,title TEXT NOT NULL,location TEXT NOT NULL,description TEXT NOT NULL,budget INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending_human' CHECK(status IN ('pending_human','approved','rejected')),proposed_by TEXT NOT NULL DEFAULT 'bot',reviewed_by TEXT,reviewed_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS saliyah_sim_citizens (id TEXT PRIMARY KEY,name TEXT NOT NULL,occupation TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
